	//------------- Counter -------------------------
	function getCounterData(obj) {
		var days = parseInt($('.days', obj).text());
		var hours = parseInt($('.hours', obj).text());
		var minutes = parseInt($('.minutes', obj).text());
		var seconds = parseInt($('.seconds', obj).text());
		return seconds + (minutes * 60) + (hours * 3600) + (days * 3600 * 24);
	}

	function setCounterData(s, obj) {
		var days = Math.floor(s / (3600 * 24));
		var hours = Math.floor((s % (60 * 60 * 24)) / (3600));
		var minutes = Math.floor((s % (60 * 60)) / 60);
		var seconds = Math.floor(s % 60);
		$('.days', obj).html(days);
		$('.hours', obj).html(hours);
		$('.minutes', obj).html(minutes);
		$('.seconds', obj).html(seconds);
	}

	var count = getCounterData($(".counter"));
	var timer = setInterval(function() {
		count--;
		if (count == 0) {
			clearInterval(timer);
			return;
		}
		setCounterData(count, $(".counter"));
	}, 1000);


	// 	------------------ TABS --------------
	$(".tab_title li").click( function(){
		var data_id = $(this).attr("data-id");
		$(".tab_content").hide();
		var $activeTab = $('.tab_content[data-id="' + data_id + '"]').show();
		$(".tab_title li").removeClass('active');
		$(this).addClass('active');
		$activeTab.find('.rb_product_swiper').each(function(){
			if (this.swiper) {
				this.swiper.update();
				this.swiper.slideTo(0, 0);
			}
		});
	});

	// 	----------- Back To Top Btn ---------------------
	$(window).scroll(function(){
		var showAfter = 100;
		if ( $(this).scrollTop() > showAfter ) { 
			$('.back_to_top').fadeIn();
		} else { 
			$('.back_to_top').fadeOut();
		}
	});
	$('.back_to_top').click(function(){
		$('html, body').animate({scrollTop : 0},800);
		return false;
	});

