document.querySelectorAll(".rb_product_swiper").forEach(function(productSlider){
	var productSliderOptions = {
		slidesPerView: 2,
		spaceBetween: 10,
		speed: 1200,
		navigation: {
			prevEl: productSlider.querySelector(".slidePrev-btn"),
			nextEl: productSlider.querySelector(".slideNext-btn")
		},
		breakpoints:{576:{slidesPerView:2},768:{slidesPerView:2},992:{slidesPerView:3},1200:{slidesPerView:4},1400:{slidesPerView:4}}
	};
	if (productSlider.dataset.autoplay === "1") {
		productSliderOptions.autoplay = {
			delay: Number(productSlider.dataset.autoplayDelay) || 3000,
			disableOnInteraction: false,
			pauseOnMouseEnter: true
		};
	}
	new Swiper(productSlider, productSliderOptions);
});

